import{_ as t,o as h,c as a,a2 as i}from"./chunks/framework.mRCPFc5l.js";const s=JSON.parse('{"title":"&quot;Một learner model luôn có uncertainty&quot;","description":"","frontmatter":{},"headers":[],"relativePath":"mental-models/uncertainty.md","filePath":"mental-models/uncertainty.md"}'),c={name:"mental-models/uncertainty.md"};function o(u,n,g,r,e,l){return h(),a("div",null,[...n[0]||(n[0]=[i('<h1 id="quot-mot-learner-model-luon-co-uncertainty-quot" tabindex="-1">&quot;Một learner model luôn có uncertainty&quot; <a class="header-anchor" href="#quot-mot-learner-model-luon-co-uncertainty-quot" aria-label="Permalink to &quot;&amp;quot;Một learner model luôn có uncertainty&amp;quot;&quot;">​</a></h1><p>Trên trang này# &quot;Một learner model luôn có uncertainty&quot; <a href="#mot-learner-model-luon-co-uncertainty">​</a> Không hệ thống nào — và không giáo viên nào, không phụ huynh nào — biết chính xác một đứa trẻ hiểu gì. Điều tốt nhất có thể làm là ước lượng tốt, và <strong>trung thực về mức độ chắc chắn của ước lượng đó</strong>.</p><h2 id="vi-sao-bat-đinh-la-khong-the-tranh-​" tabindex="-1">Vì sao bất định là không thể tránh <a href="#vi-sao-bat-đinh-la-khong-the-tranh">​</a> <a class="header-anchor" href="#vi-sao-bat-đinh-la-khong-the-tranh-​" aria-label="Permalink to &quot;Vì sao bất định là không thể tránh [​](#vi-sao-bat-đinh-la-khong-the-tranh)&quot;">​</a></h2><p>Hiểu biết nằm trong đầu learner. Nó không quan sát được trực tiếp. Tất cả những gì ta thấy là <strong>hành vi</strong> — câu trả lời, thời gian, cách diễn đạt — và từ đó suy ngược ra. Phép suy ngược này luôn nhiều-một: nhiều trạng thái hiểu biết khác nhau có thể tạo ra cùng một hành vi. Một câu trả lời đúng có thể đến từ hiểu sâu, từ thuộc dạng, từ loại trừ, hoặc từ may mắn. Không có cách nào phân biệt tuyệt đối. Đây không phải hạn chế của công nghệ. Nó là bản chất của việc đo lường một thứ không quan sát được trực tiếp.</p><h2 id="nguy-hiem-cua-su-chac-chan-gia-​" tabindex="-1">Nguy hiểm của sự chắc chắn giả <a href="#nguy-hiem-cua-su-chac-chan-gia">​</a> <a class="header-anchor" href="#nguy-hiem-cua-su-chac-chan-gia-​" aria-label="Permalink to &quot;Nguy hiểm của sự chắc chắn giả [​](#nguy-hiem-cua-su-chac-chan-gia)&quot;">​</a></h2><p>Một hệ thống lúc nào cũng có sẵn con số cho mọi ô nghe có vẻ chuyên nghiệp hơn. Thực tế nó nguy hiểm hơn: <strong>Nó dẫn tới quyết định lớn dựa trên dữ liệu mỏng.</strong> &quot;Con yếu Hình học&quot; dựa trên hai câu sai có thể dẫn tới một khoá học thêm sáu tháng — cho một vấn đề có thể không tồn tại. <strong>Nó tạo ra nhãn dán.</strong> Một con số được trình bày chắc chắn sẽ thành sự thật trong đầu mọi người, kể cả trong đầu đứa trẻ. <strong>Nó ngăn việc kiểm tra lại.</strong> Nếu hệ thống nói chắc, không ai nghĩ tới việc đo lại.</p><h2 id="nemo12-noi-ra-su-bat-đinh-cua-minh-​" tabindex="-1">Nemo12 nói ra sự bất định của mình <a href="#nemo12-noi-ra-su-bat-đinh-cua-minh">​</a> <a class="header-anchor" href="#nemo12-noi-ra-su-bat-đinh-cua-minh-​" aria-label="Permalink to &quot;Nemo12 nói ra sự bất định của mình [​](#nemo12-noi-ra-su-bat-đinh-cua-minh)&quot;">​</a></h2><p>Mỗi kết luận đi kèm một con số riêng cho độ chắc chắn. Bốn tình huống, bốn cách nói khác nhau: Ước lượngĐộ chắc chắnHệ thống nói gìThấpCao&quot;Đây là lỗ hổng thật. Nên học phần này.&quot;Thấp**Thấp****&quot;Tôi chưa biết. Cho tôi hỏi hai câu.&quot;**CaoThấp&quot;Có vẻ ổn, nhưng tôi chưa dám chắc.&quot;CaoCao&quot;Phần này con vững.&quot;Dòng thứ hai là dòng quan trọng nhất. Một hệ thống không có dòng đó sẽ đối xử với &quot;chưa biết&quot; như với &quot;yếu&quot; — và bắt rất nhiều đứa trẻ học lại thứ chúng đã biết.</p><h2 id="ba-trang-thai-khong-đuoc-gop-​" tabindex="-1">Ba trạng thái không được gộp <a href="#ba-trang-thai-khong-đuoc-gop">​</a> <a class="header-anchor" href="#ba-trang-thai-khong-đuoc-gop-​" aria-label="Permalink to &quot;Ba trạng thái không được gộp [​](#ba-trang-thai-khong-đuoc-gop)&quot;">​</a></h2><p>Trên bảng tiến độ, ba tình huống sau <strong>phải</strong> hiện khác nhau:</p><ul><li><strong>Chưa học</strong> — con chưa từng gặp phần này.</li><li><strong>Chưa đủ dữ liệu</strong> — có thể con biết, hệ thống chưa dám nói.</li><li><strong>Đã đo, chưa vững</strong> — có bằng chứng rõ là còn hụt. Gộp cả ba thành một ô trống là lỗi thiết kế phổ biến, và nó dẫn thẳng tới việc lãng phí thời gian của learner.</li></ul><h2 id="đieu-nay-thay-đoi-gi-cho-ban-​" tabindex="-1">Điều này thay đổi gì cho bạn <a href="#đieu-nay-thay-đoi-gi-cho-ban">​</a> <a class="header-anchor" href="#đieu-nay-thay-đoi-gi-cho-ban-​" aria-label="Permalink to &quot;Điều này thay đổi gì cho bạn [​](#đieu-nay-thay-đoi-gi-cho-ban)&quot;">​</a></h2><p>Nó cho bạn một câu hỏi mới để hỏi về bất kỳ nhận định nào — từ hệ thống, từ thầy cô, từ chính bạn: <strong>&quot;Cái này biết chắc, hay mới chỉ là phỏng đoán?&quot;</strong> Và một câu hỏi tiếp theo: <em>&quot;dựa trên bao nhiêu quan sát, từ bao giờ, ở bao nhiêu tình huống khác nhau?&quot;</em> Câu trả lời rất thường là: một bài kiểm tra, cách đây hai tháng, một dạng bài. Đó là cơ sở quá mỏng cho một quyết định về sáu tháng tiếp theo của một đứa trẻ.</p><h2 id="đieu-nay-cung-đung-voi-chinh-ban-​" tabindex="-1">Điều này cũng đúng với chính bạn <a href="#đieu-nay-cung-đung-voi-chinh-ban">​</a> <a class="header-anchor" href="#đieu-nay-cung-đung-voi-chinh-ban-​" aria-label="Permalink to &quot;Điều này cũng đúng với chính bạn [​](#đieu-nay-cung-đung-voi-chinh-ban)&quot;">​</a></h2><p>Bạn cũng có một learner model về con mình — nó chỉ nằm trong đầu thay vì trong cơ sở dữ liệu. Và nó cũng có bất định, thường lớn hơn ta tưởng:</p><ul><li>&quot;Con lười&quot; — hay con đang không hiểu và ngại nói?</li><li>&quot;Con không thích Toán&quot; — hay con từng bị chê một lần và từ đó tránh?</li><li>&quot;Con giỏi Văn&quot; — dựa trên mấy bài, từ khi nào? Không câu nào trong ba câu này sai. Nhưng cả ba đều là kết luận, và cả ba đều đáng được hỏi lại &quot;dựa vào đâu&quot;. Một thói quen đáng có Khi nghe một nhận định về con — kể cả từ chính mình — thử thêm vào cuối câu: <em>&quot;…dựa trên những gì tôi đã thấy cho tới lúc này.&quot;</em> Nó không đổi nội dung, nhưng nó giữ cho kết luận ở đúng vị trí của một kết luận, thay vì trở thành một đặc điểm cố định của đứa trẻ. Một hệ thống dám nói &quot;tôi chưa biết&quot; đáng tin hơn nhiều một hệ thống lúc nào cũng có sẵn câu trả lời. <a href="/mental-models/cuoc-thi">Không phải cuộc thi nào cũng đáng tham gia →</a></li></ul>',16)])])}const b=t(c,[["render",o]]);export{s as __pageData,b as default};
